import z3

def search_counterexample(n, target_r, target_rd):
    # Search for an undirected graph G on n vertices with:
    # 1. Connected (HasRadius)
    # 2. Radius >= target_r
    # 3. Exists a Roman dominating function of weight <= target_rd
    # If target_r + 1 > target_rd, this is a COUNTEREXAMPLE!
    s = z3.Solver()

    # Adjacency matrix: adj[i][j]
    adj = [[z3.Bool(f'e_{i}_{j}') for j in range(n)] for i in range(n)]
    for i in range(n):
        s.add(z3.Not(adj[i][i]))
        for j in range(n):
            s.add(adj[i][j] == adj[j][i])

    # Distance matrix: dist[i][j] in {0..n}
    dist = [[z3.Int(f'd_{i}_{j}') for j in range(n)] for i in range(n)]
    for i in range(n):
        for j in range(n):
            s.add(dist[i][j] >= 0, dist[i][j] <= n)
            if i == j:
                s.add(dist[i][j] == 0)
            else:
                s.add(dist[i][j] >= 1)
                # If adjacent, dist is 1
                s.add(z3.Implies(adj[i][j], dist[i][j] == 1))
                # Triangle inequality / shortest path constraints
                for k in range(n):
                    s.add(dist[i][j] <= dist[i][k] + dist[k][j])

    # For every pair (i, j) with dist[i][j] > 1, there must be a neighbor k of i with dist[k][j] = dist[i][j] - 1
    for i in range(n):
        for j in range(n):
            if i != j:
                # either dist == 1 and adj[i][j], or exists k
                s.add(z3.Implies(dist[i][j] == 1, adj[i][j]))
                conds = [z3.And(adj[i][k], dist[k][j] == dist[i][j] - 1) for k in range(n) if k != i]
                s.add(z3.Or(dist[i][j] == 1, z3.Or(conds)))

    # HasRadius: every pair has finite distance <= n-1
    for i in range(n):
        for j in range(n):
            s.add(dist[i][j] <= n - 1)

    # Radius >= target_r: for EVERY vertex v, max_u dist[v][u] >= target_r
    # That means for every v, exists u such that dist[v][u] >= target_r
    for v in range(n):
        s.add(z3.Or([dist[v][u] >= target_r for u in range(n)]))

    # Roman dominating function f : {0, 1, 2}
    f = [z3.Int(f'f_{i}') for i in range(n)]
    for i in range(n):
        s.add(f[i] >= 0, f[i] <= 2)
        # If f[i] == 0, exists neighbor j with f[j] == 2
        s.add(z3.Implies(f[i] == 0, z3.Or([z3.And(adj[i][j], f[j] == 2) for j in range(n) if j != i])))

    # Weight <= target_rd
    s.add(z3.Sum(f) <= target_rd)

    if s.check() == z3.sat:
        m = s.model()
        edges = []
        for i in range(n):
            for j in range(i+1, n):
                if z3.is_true(m[adj[i][j]]):
                    edges.append((i, j))
        f_vals = [m[f[i]].as_long() for i in range(n)]
        print(f'FOUND SAT for n={n}, target_r={target_r}, target_rd={target_rd}!')
        print(f'Edges: {edges}')
        print(f'f: {f_vals}')
        return edges
    else:
        print(f'UNSAT for n={n}, target_r={target_r}, target_rd={target_rd}')
        return None

# We want target_r + 1 > target_rd
# For example: r=3, rd=3 (r+1 = 4 > 3)
